    "segments": [
      {
        "start": 0,
        "end": 1.36,
        "text": "卸能避风大功能的"
      },
      {
        "start": 1.36,
        "end": 2.52,
        "text": "一定是领导下班前"
      },
      {
        "start": 2.52,
        "end": 3.8,
        "text": "让你做了那份PPT"
      },
      {
        "start": 3.8,
        "end": 5.28,
        "text": "以前对营业业造谱板"
      },
      {
        "start": 5.28,
        "end": 6.44,
        "text": "余剧余剧想文案"
      },
      {
        "start": 6.44,
        "end": 7.64,
        "text": "1.1.条格式"
      },
      {
        "start": 7.64,
        "end": 8.36,
        "text": "这趟半天"
      },
      {
        "start": 8.36,
        "end": 9.44,
        "text": "营业都做不出来"
      },
      {
        "start": 9.44,
        "end": 10.48,
        "text": "现在有了斗宝"
      },
      {
        "start": 10.48,
        "end": 11.48,
        "text": "几分钟就表定"
      },
      {
        "start": 11.48,
        "end": 12.72,
        "text": "今天我就手法手教你"
      },
      {
        "start": 12.72,
        "end": 14.16,
        "text": "我会用斗宝做PPT"
      },
      {
        "start": 14.16,
        "end": 15.32,
        "text": "第1物整理文案"
      },
      {
        "start": 15.32,
        "end": 16.32,
        "text": "打开专家模式"
      },
      {
        "start": 16.32,
        "end": 17.4,
        "text": "点击帮我写作"
      },
      {
        "start": 17.4,
        "end": 18.84,
        "text": "把你想要上层的主题"
      },
      {
        "start": 18.84,
        "end": 19.6,
        "text": "输入进去"
      },
      {
        "start": 19.6,
        "end": 20.88,
        "text": "斗宝瞬间就能帮你吧"
      },
      {
        "start": 20.88,
        "end": 22.08,
        "text": "你带接斗的核心事件"
      },
      {
        "start": 22.08,
        "end": 22.8,
        "text": "总结关大"
      },
      {
        "start": 22.8,
        "end": 25.04,
        "text": "这不比我一点点产生量方便多了"
      },
      {
        "start": 25.04,
        "end": 27.36,
        "text": "而且你想让他帮你改具体的某个东西"
      },
      {
        "start": 27.36,
        "end": 28.6,
        "text": "也可以直接输入指令"
      },
      {
        "start": 28.6,
        "end": 29.36,
        "text": "包包板结尾"
      },
      {
        "start": 29.36,
        "end": 30.76,
        "text": "修改的更加简洁有力"
      },
      {
        "start": 30.76,
        "end": 31.68,
        "text": "更有感染力"
      },
      {
        "start": 31.68,
        "end": 32.52,
        "text": "这样样的结尾"
      },
      {
        "start": 32.52,
        "end": 34.04,
        "text": "就这样税零零的出来了"
      },
      {
        "start": 34.04,
        "end": 35.68,
        "text": "最后整体认识的修改一下"
      },
      {
        "start": 35.68,
        "end": 36.68,
        "text": "早知就定下来了"
      },
      {
        "start": 36.68,
        "end": 37.64,
        "text": "是不是超方便"
      },
      {
        "start": 37.64,
        "end": 39.28,
        "text": "然后再一点击PPT声声"
      },
      {
        "start": 39.28,
        "end": 40.6,
        "text": "把你的需求全写上"
      },
      {
        "start": 40.6,
        "end": 42,
        "text": "一番PPT就出来了"
      },
      {
        "start": 42,
        "end": 42.84,
        "text": "最关键的是"
      },
      {
        "start": 42.84,
        "end": 44.48,
        "text": "如果你不满意正义业的内容"
      },
      {
        "start": 44.48,
        "end": 45.24,
        "text": "后来是配图"
      },
      {
        "start": 45.24,
        "end": 45.96,
        "text": "还是排败"
      },
      {
        "start": 45.96,
        "end": 46.96,
        "text": "动了单独修改"
      },
      {
        "start": 46.96,
        "end": 48,
        "text": "不用再重新声声"
      },
      {
        "start": 48,
        "end": 49.24,
        "text": "只需要一定指令"
      },
      {
        "start": 49.24,
        "end": 52.6,
        "text": "配图排败 一步到位 与其飞机其实受除PPT"
      },
      {
        "start": 52.6,
        "end": 55,
        "text": "如果把这些反正的机械工作交给头包"
      },
      {
        "start": 55,
        "end": 57,
        "text": "把机械穿着你真正想讲的内容上"
      }
    ],
